var REF_V = 2; // 1.2.0: el ref guarda también el emblema de cada élite (lo de v1 se vuelve a pedir una vez)
var IDKEY = 'gn:bld:id:';
var mem = {}, inflight = {}, buildInfo = { id: null, at: 0 }, ident = null, identInflight = null;

// ---------------------------------------------------------------- identidad: profesiones y élites (BUI-1)
// profs = /v2/professions?ids=all, specs = sus /v2/specializations → { v, profs: { 1..9 }, elites: { id } } con los íconos
// oficiales: el de la profesión (icon, icon_big) y, por élite, su emblema (profession_icon, profession_icon_big).
function normalizeIdentity(profs, specs) {
  var byId = {}, out = { v: 1, profs: {}, elites: {} };
  (specs || []).forEach(function (s) { if (s && s.id) byId[s.id] = s; });
  (profs || []).forEach(function (p) {
    var code = profCode(p && p.id);
    if (!code) return;
    var elites = (p.specializations || []).map(function (id) { return byId[id]; }).filter(function (s) { return s && s.elite; });
    elites.forEach(function (s) {
      out.elites[s.id] = { id: s.id, name: s.name, prof: code, icon: s.profession_icon || s.icon || '',
        iconBig: s.profession_icon_big || s.profession_icon || s.icon || '', specIcon: s.icon || '', background: s.background || '' };
    });
    out.profs[code] = { code: code, id: p.id, name: p.name, icon: p.icon || '', iconBig: p.icon_big || p.icon || '',
      elites: elites.map(function (s) { return s.id; }) };
  });
  return out;
}
// identity(opts) → Promise<identidad>. Un pedido de profesiones y uno de especializaciones; se guarda por versión del juego.
function identity(opts) {
  opts = opts || {};
  var f = opts.fetch;
  return gameBuild(f).then(function (bid) {
    var key = IDKEY + LANG + ':' + (bid || 0);
    if (!opts.force && ident && ident.key === key) return ident;
    var S = store();
    var ready = S && typeof S.ready === 'function' ? S.ready() : Promise.resolve();
    return Promise.resolve(ready).then(function () {
      if (!opts.force && S) { var c = S.get(key); if (c && c.v === 1 && c.profs && c.profs[1]) { ident = c; return c; } }
      if (identInflight) return identInflight;
      identInflight = getJSON(API + '/v2/professions?ids=all&v=latest&lang=' + LANG, f).then(function (profs) {
        var ids = [];
        (profs || []).forEach(function (p) { ids = ids.concat(p.specializations || []); });
        return many('/v2/specializations', ids, f).then(function (specs) {
          var x = normalizeIdentity(profs, specs);
          x.key = key; x.gameBuild = bid || 0;
          ident = x; identInflight = null;
          if (S) { try { S.set(key, x); pruneIdent(S, key); } catch (_) {} }
          return x;
        });
      }).then(null, function (e) { identInflight = null; throw e; });
      return identInflight;
    });
  });
}
function identitySync() { return ident; }
function pruneIdent(S, keep) {
  if (typeof S.keys !== 'function') return;
  S.keys().forEach(function (k) { if (k.indexOf(IDKEY + LANG + ':') === 0 && k !== keep) S.del(k); });
}

// BUI-1: identidad oficial. Dos profesiones de mentira con la forma real de /v2/professions?ids=all y /v2/specializations.
const R_ = 'https://render.guildwars2.com/file/';
const IPROFS = [{ id: 'Guardian', name: 'Guardián', icon: R_ + 'g.png', icon_big: R_ + 'G.png', specializations: [16, 27, 62] },
  { id: 'Warrior', name: 'Guerrero', icon: R_ + 'w.png', icon_big: R_ + 'W.png', specializations: [4, 74] },
  { id: 'Commander', name: '?', specializations: [] }];
const ISPECS = [{ id: 16, name: 'Celo', elite: false, icon: R_ + 's16.png' },
  { id: 27, name: 'Cazadragones', elite: true, icon: R_ + 's27.png', profession_icon: R_ + 'e27.png', profession_icon_big: R_ + 'E27.png', background: R_ + 'b27.png' },
  { id: 62, name: 'Abrasador', elite: true, icon: R_ + 's62.png', profession_icon: R_ + 'e62.png' },
  { id: 4, name: 'Fuerza', elite: false }, { id: 74, name: 'Paragón', elite: true, profession_icon: R_ + 'e74.png', profession_icon_big: R_ + 'E74.png' }];

test('BUI-1 normalizeIdentity: profesiones con su ícono grande y élites con su emblema, en el orden de la API', () => {
  const x = R.normalizeIdentity(IPROFS, ISPECS);
  assert.deepEqual(Object.keys(x.profs), ['1', '2'], 'lo que no es profesión se descarta');
  assert.equal(x.profs[1].iconBig, R_ + 'G.png');
  assert.deepEqual(x.profs[1].elites, [27, 62], 'solo élites');
  assert.equal(x.elites[27].iconBig, R_ + 'E27.png');
  assert.equal(x.elites[27].background, R_ + 'b27.png');
  assert.equal(x.elites[62].iconBig, R_ + 'e62.png', 'sin ícono grande, el chico');
  assert.equal(x.elites[74].prof, 2);
});

test('BUI-1 identity(): un pedido de profesiones y uno de especializaciones; la segunda vez, nada', async () => {
  R._test.reset();
  const log = [];
  const f = async (url) => {
    log.push(url);
    const u = new URL(url);
    const body = u.pathname === '/v2/build' ? { id: 209026 } : u.pathname === '/v2/professions' ? IPROFS
      : u.pathname === '/v2/specializations' ? ISPECS.filter((s) => u.searchParams.get('ids').split(',').includes(String(s.id))) : null;
    return { ok: !!body, status: body ? 200 : 404, text: async () => JSON.stringify(body) };
  };
  assert.equal(R.identitySync(), null);
  const x = await R.identity({ fetch: f });
  assert.equal(x.elites[74].name, 'Paragón');
  assert.equal(x.gameBuild, 209026);
  assert.match(log.find((u) => /\/v2\/professions\?/.test(u)), /ids=all&v=latest&lang=es/);
  assert.equal(R.identitySync(), x, 'queda a mano para dibujar sin esperar');
  const n = log.length;
  await R.identity({ fetch: f });
  assert.equal(log.length, n, 'sin pedidos nuevos');
});

test('BUI-1 la ficha lleva el emblema de su élite; lo guardado con el formato viejo se vuelve a pedir', () => {
  const sp = SPECS.map((s) => (s.id === 27 ? Object.assign({}, s, { profession_icon: 'e.png', profession_icon_big: 'E.png' }) : s));
  const ref = R.normalize({ prof: PROF, specs: sp, traits: TRAITS, skills: SKILLS });
  assert.equal(ref.v, 2);
  const b = C.empty(1);
  b.specs = [{ id: 16, traits: [1, 1, 1] }, { id: 42, traits: [1, 1, 1] }, { id: 27, traits: [1, 1, 1] }];
  const v = R.resolve(b, ref);
  assert.equal(v.specs[2].profIconBig, 'E.png');
  assert.equal(v.profIconBig, 'G.png');
});

// BUI-1: emblema oficial. Con élite, el de la élite; si no, el de la profesión; sin datos, un hueco del mismo tamaño.
// ident = GNBldRef.identitySync() (o el que se pase). Más de 32 px usa el ícono grande. opts: { ident, label, cls }
function emblemOf(prof, elite, big, ident) {
  var R = root.GNBldRef;
  ident = ident || (R && typeof R.identitySync === 'function' ? R.identitySync() : null);
  var e = ident && elite ? ident.elites[elite] : null, p = ident && prof ? ident.profs[prof] : null;
  if (e) return { src: big ? e.iconBig : e.icon, name: e.name };
  if (p) return { src: big ? p.iconBig : p.icon, name: p.name };
  return { src: '', name: '' };
}
function emblem(prof, elite, size, opts) {
  opts = opts || {};
  var x = emblemOf(prof, elite, size > 32, opts.ident);
  return '<span class="bld-emb' + (opts.cls ? ' ' + opts.cls : '') + '"' + (opts.label && x.name ? ' title="' + esc(x.name) + '"' : '') + '>' +
    img(x.src, opts.label ? x.name : '', size, '') + '</span>';
}

